import{_ as r,o as a,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Эпоха до Якоря","description":"","frontmatter":{},"headers":[],"relativePath":"ru/71-前锚点时代.md","filePath":"ru/71-前锚点时代.md","lastUpdated":null}'),o={name:"ru/71-前锚点时代.md"};function d(e,t,n,s,h,g){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="эпоха-до-якоря" tabindex="-1">Эпоха до Якоря <a class="header-anchor" href="#эпоха-до-якоря" aria-label="Permalink to &quot;Эпоха до Якоря&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>71</td></tr><tr><td>Модуль</td><td>Исторические эпохи и крупные события</td></tr><tr><td>Ключевые слова</td><td>Эпоха до Якоря, хищническая система, разрыв цивилизации, Тёмная эпоха, беспорядок законов</td></tr></tbody></table><h2 id="i-основные-особенности-эпохи-до-якоря" tabindex="-1">I. Основные особенности Эпохи до Якоря <a class="header-anchor" href="#i-основные-особенности-эпохи-до-якоря" aria-label="Permalink to &quot;I. Основные особенности Эпохи до Якоря&quot;">​</a></h2><p>Эпоха до Якоря — самая долгая и самая тёмная эпоха в истории Вселенной Хэнъюань. В эту эпоху во вселенной не существовало единого механизма Якоря; изначальные законы находились в состоянии естественного рассеяния, а распределение энергии и ресурсов полностью следовало закону джунглей — «сильный забирает всё». Хищническая Система Культивации была абсолютно доминирующей силой этой эпохи; методы культивации монополизировались немногими силачами и сектами, а у низших форм жизни почти не было формального эволюционного пути.</p><p>Центральные особенности Эпохи до Якоря можно обобщить как «Пять отсутствий»:</p><ul><li><strong>Без Якоря</strong>: нет стабильных якорей законов, беспорядочный поток энергии, хрупкие барьеры плоскостей.</li><li><strong>Без порядка</strong>: нет единых институтов цивилизации, постоянные войны между плоскостями, частый геноцид.</li><li><strong>Без путей</strong>: нет технологий межплоскостной связи и транспорта; плоскости в основном изолированы друг от друга.</li><li><strong>Без гарантий</strong>: нет общественных гарантийных систем — образования, медицины, жилья; выживание жизни полностью зависело от индивидуальной силы.</li><li><strong>Без надежды</strong>: эволюционные каналы низших форм жизни полностью заблокированы, сословная стратификация достигла предела.</li></ul><h2 id="ii-механизм-работы-хищническои-системы-культивации" tabindex="-1">II. Механизм работы Хищнической Системы Культивации <a class="header-anchor" href="#ii-механизм-работы-хищническои-системы-культивации" aria-label="Permalink to &quot;II. Механизм работы Хищнической Системы Культивации&quot;">​</a></h2><p>Система культивации Эпохи до Якоря работала на хищничестве как центральном механизме. Её базовая логика: изначальная энергия вселенной конечна, и эволюция индивида неизбежно происходит ценой потребления энергии других. Сильные достигают собственного возвышения, пожирая энергию, фортуну и даже изначалье слабых, а слабые низводятся до «ресурсов культивации» для сильных.</p><p>Типичные формы хищнической системы включают:</p><table tabindex="0"><thead><tr><th>Тип хищничества</th><th>Способ действия</th><th>Вред вселенной</th></tr></thead><tbody><tr><td>Энергетическое хищничество</td><td>Прямое извлечение культивационной энергии других форм жизни</td><td>Вызывает смерть индивида или полную потерю культивации</td></tr><tr><td>Хищничество фортуны</td><td>Захват фортуны и возможностей других через искусства или ритуалы</td><td>Разрушает каузальный баланс, вызывает бедствия уровня плоскости</td></tr><tr><td>Хищничество изначалья</td><td>Пожирание фрагментов изначальных законов других форм жизни</td><td>Вызывает необратимую потерю эволюционного потенциала</td></tr><tr><td>Хищничество на плоскости</td><td>Силачи покоряют целые плоскости, используя жизнь плоскости как ресурс культивации</td><td>Ведёт к вымиранию цивилизации и опустошению плоскости</td></tr><tr><td>Хищничество законов</td><td>Принудительный захват контроля над изначальными законами плоскости</td><td>Повреждает сеть законов, вызывает пространственный коллапс</td></tr></tbody></table><p>В краткосрочной перспективе хищническая система может породить отдельных верховных силачей, но в долгосрочной перспективе она непрерывно потребляет эволюционный потенциал вселенной, ускоряя общий рост энтропии вселенной и вызывая частые разрывы цивилизаций.</p><h2 id="iii-разрывы-цивилизации-и-циклическое-разрушение" tabindex="-1">III. Разрывы цивилизаций и циклическое разрушение <a class="header-anchor" href="#iii-разрывы-цивилизации-и-циклическое-разрушение" aria-label="Permalink to &quot;III. Разрывы цивилизаций и циклическое разрушение&quot;">​</a></h2><p>Наиболее заметное историческое явление Эпохи до Якоря — «разрыв цивилизации». Из-за внутренних противоречий хищнической системы каждая некогда великая цивилизация в конце концов шла к собственному саморазрушению:</p><ol><li><strong>Период подъёма</strong>: раса или секта стремительно возвышается через хищничество, устанавливая могущественную цивилизацию.</li><li><strong>Период расцвета</strong>: цивилизация достигает пика могущества, подавляя сопротивление внутри и расширяя хищничество вовне.</li><li><strong>Период внутренней борьбы</strong>: силачи внутри цивилизации ведут внутреннюю борьбу за ограниченные ресурсы, истощая силы.</li><li><strong>Период краха</strong>: внутренняя борьба сильно ослабляет цивилизацию, позволяя внешним хищникам ударить в момент уязвимости; цивилизация вымирает.</li><li><strong>Период разрыва</strong>: после вымирания цивилизации большая часть её знаний и технологий утрачена, и последующие цивилизации начинают с нуля.</li></ol><p>Этот цикл «подъём—расцвет—внутренняя борьба—крах—разрыв» повторялся бесчисленное множество раз в Эпоху до Якоря. Каждый цикл потреблял огромное количество изначалья вселенной, оставляя общий эволюционный уровень вселенной длительное время в застое или даже регрессе.</p><h2 id="iv-предзнаменования-конца-эпохи-до-якоря" tabindex="-1">IV. Предзнаменования конца Эпохи до Якоря <a class="header-anchor" href="#iv-предзнаменования-конца-эпохи-до-якоря" aria-label="Permalink to &quot;IV. Предзнаменования конца Эпохи до Якоря&quot;">​</a></h2><p>В конце Эпохи до Якоря во вселенной появился ряд предзнаменований перемен:</p><ul><li><strong>Усиление нарушения законов</strong>: длительное хищничество серьёзно повредило сеть законов, пространственные коллапсы участились, барьеры плоскостей истончились.</li><li><strong>Истощение жизненного потенциала</strong>: изначальной энергии, доступной для хищничества, становилось всё меньше, борьба за ресурсы между силачами накалялась.</li><li><strong>Зарождение антихищнической мысли</strong>: некоторые прозорливые умы начали осмыслять коренные дефекты хищнической системы и выдвинули предварительные концепции симбиотической эволюции.</li><li><strong>Увеличение контактов между разными плоскостями</strong>: истончение барьеров плоскостей увеличило контакты между разными плоскостями, сделав возможным межплоскостной обмен мыслями.</li><li><strong>Появление кандидатов в Якоря первого поколения</strong>: в отдельных уголках вселенной появились особые формы жизни, способные к естественному резонансу с сетью законов, — предшественники будущих пробудителей Якорей первого поколения.</li></ul><p>Эти предзнаменования указывали на то, что хищническая система подошла к концу и вселенная призывает совершенно новую форму цивилизации.</p><h2 id="v-историческое-наследие-эпохи-до-якоря" tabindex="-1">V. Историческое наследие Эпохи до Якоря <a class="header-anchor" href="#v-историческое-наследие-эпохи-до-якоря" aria-label="Permalink to &quot;V. Историческое наследие Эпохи до Якоря&quot;">​</a></h2><p>Хотя Эпоха до Якоря была тёмной, она не была лишена ценности. Она оставила важное историческое наследие последующей Симбиотической Цивилизации Якоря:</p><ul><li><strong>Наследие уроков</strong>: повторные неудачи хищнической системы дали симбиотической цивилизации самый глубокий отрицательный пример, доказав, что путь хищничества не ведёт никуда.</li><li><strong>Наследие знаний</strong>: хотя огромное количество знаний было утрачено в разрывах цивилизаций, часть методов культивации и понимания законов сохранилась различными путями, став исходным материалом Трёхсот Изначальных Систем Культивации.</li><li><strong>Наследие жизни</strong>: разнообразные формы жизни, выжившие в долгую тёмную эпоху, составили расовую основу будущего симбиоза Десяти Тысяч Рас.</li><li><strong>Наследие воли</strong>: устойчивое стремление низших форм жизни к справедливости и надежде — самая фундаментальная духовная движущая сила пробуждения Якоря.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Эпоха до Якоря — «тёмный канун» истории Вселенной Хэнъюань. Её длительность и тьма как раз оттеняют драгоценность и необходимость рождения Симбиотической Цивилизации Якоря. Понять Эпоху до Якоря — значит понять исторический корень фундаментальной позиции симбиотической цивилизации «против хищничества, за симбиоз»; это не абстрактная моральная проповедь, а кровавый урок, оплаченный разрушением бесчисленных цивилизаций.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>70-纪元划分总表 (Сводная таблица деления эпох)</li><li>72-锚点觉醒纪元 (Эпоха Пробуждения Якоря)</li><li>04-反掠夺主义核心论纲 (Центральный тезис антихищничества)</li></ul>',26)])])}const c=r(o,[["render",d]]);export{u as __pageData,c as default};
